def common_prefix(arr, n):
    """Write a function to find the longest common prefix in the given set of strings."""
    if not arr or n <= 0:
        return ""
    strings = arr[:n]
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix
